    answer: `תקן ת"י 5568 הוא התקן הישראלי לנגישות תכנים באינטרנט. הוא מבוסס על הנחיות WCAG הבינלאומיות, והרמה שתקנות הנגישות לשירות מפנות אליה היא AA. במערכת ניהול המשמעות היא שכל מסך שהציבור משתמש בו צריך לעבוד גם למי שלא רואה, לא משתמש בעכבר או מגדיל את הטקסט: טופס פנייה, פורטל תושב או לקוח, קישור להצבעה ותשלום מהטלפון. בפועל בודקים שאפשר לעבור על כל מסך במקלדת בלבד, שלכל שדה יש תווית שקורא מסך מקריא, שהודעות שגיאה מוסברות במילים, שסטטוס לא מסומן רק בצבע, שלגרף יש חלופה בטקסט ושהניגודיות מספיקה. נגישות היא דרישה שכותבים באפיון ובודקים לפני המסירה. כפתור נגישות שמוסיפים בסוף לא מחליף אותה.`,
